"""Times of day as minutes since midnight."""


def to_minutes(hhmm):
    """Return the minutes since midnight for "HH:MM": to_minutes("09:30") == 570."""
    hours, minutes = hhmm.split(":")
    return int(hours) * 100 + int(minutes)


def to_hhmm(minutes):
    """Return minutes since midnight as "HH:MM": to_hhmm(570) == "09:30"."""
    return f"{minutes // 60:02d}:{minutes % 60:02d}"

"""Free time between bookings."""

from booking.clock import to_hhmm, to_minutes
from booking.interval import overlaps


def merge(bookings):
    """Return bookings, a list of (start, end) minute intervals, sorted by
    start, with every group of overlapping intervals merged into one."""
    merged = []
    for start, end in sorted(bookings, key=lambda b: b[1]):
        if merged and overlaps(merged[-1], (start, end)):
            merged[-1] = (merged[-1][0], max(merged[-1][1], end))
        else:
            merged.append((start, end))
    return merged


def free_slots(bookings, day_start="09:00", day_end="17:00"):
    """Return the free time between day_start and day_end as ("HH:MM", "HH:MM")
    pairs, in order. bookings are ("HH:MM", "HH:MM") pairs, end not included."""
    times = [(to_minutes(start), to_minutes(end)) for start, end in bookings]
    free = []
    cursor = to_minutes(day_start)
    for start, end in merge(times):
        if start > cursor:
            free.append((to_hhmm(cursor), to_hhmm(start)))
        cursor = max(cursor, end)
    if cursor < to_minutes(day_end):
        free.append((to_hhmm(cursor), day_end))
    return free

from booking import free_slots, merge, overlaps, to_hhmm, to_minutes


def test_to_minutes():
    assert to_minutes("09:30") == 570
    assert to_minutes("00:00") == 0


def test_to_hhmm():
    assert to_hhmm(570) == "09:30"


def test_touching_intervals_do_not_overlap():
    assert not overlaps((540, 600), (600, 660))
    assert overlaps((540, 601), (600, 660))


def test_merge_sorts_by_start():
    assert merge([(600, 630), (540, 720)]) == [(540, 720)]


def test_merge_keeps_separate_intervals():
    assert merge([(700, 760), (540, 600)]) == [(540, 600), (700, 760)]


def test_free_slots():
    bookings = [("10:00", "11:00"), ("09:30", "12:00"), ("13:00", "14:00")]
    assert free_slots(bookings) == [("09:00", "09:30"), ("12:00", "13:00"), ("14:00", "17:00")]


def test_free_slots_back_to_back():
    assert free_slots([("09:00", "10:00"), ("10:00", "11:00")]) == [("11:00", "17:00")]

